Bash(/tmp/hero_bg_check.py << 'EOF'
import asyncio
from playwright.async_api import async_playwright

pages = ["dopros-ifns", "subsidiarnaya-otvetstvennost", "nalogovye-spory"]

async def check_hero_bg\(browser, slug\):
    page = await browser.new_page\(viewport={"width": 1280, "height": 800}\)
    url = f"https://ant.partners/test/{slug}.html"

    await page.goto\(url, wait_until="networkidle", timeout=30000\)
    await page.wait_for_timeout\(2000\)

    # Deep hero background inspection
    result = await page.evaluate\('''\(\) => {
        const hero = document.querySelector\('.hero, .hero-section, [class*="hero"]'\);
        if \(!hero\) return {error: 'NO_HERO_ELEMENT'};

        const style = window.getComputedStyle\(hero\);
        const bg_image = style.backgroundImage;
        const bg_color = style.backgroundColor;
        const bg_size = style.backgroundSize;
        const bg_position = style.backgroundPosition;

        // Check pseudo-elements
        const before = window.getComputedStyle\(hero, '::before'\);
        const after = window.getComputedStyle\(hero, '::after'\);

        return {
            element: hero.className,
            bg_image: bg_image,
            bg_color: bg_color,
            bg_size: bg_size,
            bg_position: bg_position,
            before_bg: before.backgroundImage,
            after_bg: after.backgroundImage,
            html_bg_attr: hero.style.backgroundImage || 'none'
        };
    }'''\)

    await page.close\(\)
    return slug, result

async def main\(\):
    async with async_playwright\(\) as p:
        browser = await p.chromium.launch\(headless=True\)
        for slug in pages:
            slug_name, data = await check_hero_bg\(browser, slug\)
            print\(f"{slug_name:40s} | {data.get\('bg_image', 'ERROR'\)[:80]}"\)
        await browser.close\(\)

asyncio.run\(main\(\)\)
EOF)

